<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/pdf_documents.php';require_permission('contracts.send');
$id=(int)($_GET['id']??$_POST['id']??0);$stmt=db()->prepare('SELECT ct.*,c.company_name,c.tax_id,c.country,c.city,c.address,c.email client_email,c.contact_name client_contact FROM contracts ct JOIN clients c ON c.id=ct.client_id WHERE ct.id=?');$stmt->execute([$id]);$contract=$stmt->fetch();if(!$contract){http_response_code(404);exit('Contrato no encontrado.');}$pageTitle='Enviar '.$contract['contract_number'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$to=strtolower(trim((string)($_POST['to']??'')));$subject=trim((string)($_POST['subject']??''));$message=trim((string)($_POST['message']??''));if(!filter_var($to,FILTER_VALIDATE_EMAIL))$errors[]='El email no es válido.';if($subject==='')$errors[]='El asunto es obligatorio.';if(!$errors){$url=app_url('contract_public.php?token='.$contract['public_token']);$html='<!doctype html><html><body style="margin:0;padding:24px;background:#edf3f7;font-family:Arial,sans-serif;color:#183247"><div style="max-width:680px;margin:auto;background:#fff;border:1px solid #d8e3ea;border-radius:18px;overflow:hidden"><div style="height:7px;background:#ff5300"></div><div style="padding:28px"><h2 style="margin-top:0;color:#002f57">'.e($contract['title']).'</h2><p style="line-height:1.6">'.nl2br(e($message?:'Adjuntamos para su revisión el contrato de servicio. Puede abrirlo, aprobarlo o rechazarlo desde el enlace seguro.')).'</p><div style="background:#f6fafc;border:1px solid #d8e3ea;border-radius:12px;padding:15px;margin:18px 0"><strong>'.e($contract['contract_number']).'</strong><br><span style="color:#657b8c">'.e($contract['company_name']).'</span></div><p><a href="'.e($url).'" style="display:inline-block;background:#0074c7;color:#fff;text-decoration:none;padding:13px 20px;border-radius:10px;font-weight:bold">REVISAR Y APROBAR CONTRATO</a></p><p style="font-size:12px;color:#657b8c">Después de la aprobación, el PDF definitivo quedará disponible para firma.</p></div></div></body></html>';try{$pdfBytes=contract_pdf_bytes($contract);}catch(Throwable $exception){$pdfBytes='';$errors[]='No fue posible generar el PDF adjunto: '.$exception->getMessage();}$attachments=[];if($pdfBytes!==''){$filename=preg_replace('/[^A-Za-z0-9._-]+/','-',(string)$contract['contract_number']).'.pdf';$attachments[]=['filename'=>$filename,'mime'=>'application/pdf','content'=>$pdfBytes];}$result=$errors?['success'=>false,'error'=>'No se pudo preparar el documento.']:send_system_email($to,$subject,$html,$attachments);if($result['success']){db()->prepare("UPDATE contracts SET status='sent',sent_at=NOW(),recipient_email=? WHERE id=?")->execute([$to,$id]);log_activity('Contrato enviado con PDF',(int)$contract['client_id'],null,$to);flash('success','Contrato enviado correctamente con el PDF adjunto.');redirect('contract_view.php?id='.$id);}elseif(!$errors)$errors[]='No fue posible enviar: '.$result['error'];}}
require __DIR__.'/includes/header.php';?><?php foreach($errors as$error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?><form method="post" class="panel"><div class="panel-header"><div><h2>Enviar contrato para aprobación</h2><span class="table-sub">El cliente recibirá un enlace seguro de aprobación y una copia PDF completa adjunta al email.</span></div></div><div class="panel-body form-grid"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><label>Destinatario *<input type="email" name="to" required value="<?=e($_POST['to']??$contract['recipient_email']??$contract['client_email'])?>"></label><label class="full">Asunto *<input name="subject" required value="<?=e($_POST['subject']??('Contrato '.$contract['contract_number'].' · '.$contract['company_name']))?>"></label><label class="full">Mensaje<textarea name="message"><?=e($_POST['message']??'')?></textarea></label><div class="full form-actions"><a class="btn btn-light" href="contract_view.php?id=<?=$id?>">Cancelar</a><button class="btn btn-primary">ENVIAR CONTRATO + PDF</button></div></div></form><?php require __DIR__.'/includes/footer.php';?>
